on conflict (id) do nothing;

insert into public.propiedades (
  id, inmobiliaria_id, titulo, tipo, operacion, precio, ciudad, sector, provincia,
  latitude, longitude, habitaciones, banos, parqueos, metros, resumen, descripcion,
  amenidades, cerca_de, ano_construccion, mantenimiento_usd, confotur, en_plano, entrega,
  imagen, costera
) values
  ('piantini-torre-ambar', '00000000-0000-4000-8000-000000000001'::uuid, 'Apartamento moderno en Torre Ámbar', 'Apartamento', 'Venta', 285000, 'Santo Domingo', 'Piantini', 'Distrito Nacional', 18.471, -69.939, 2, 2.5, 2, 145, 'A pasos de Ágora Mall y Blue Mall, piso alto con vista a la ciudad.', 'Apartamento en piso 14 con terminaciones en porcelanato, cocina abierta con isla y área de lavado independiente. El edificio tiene planta eléctrica full, gas común y seguridad 24/7. Ideal para profesionales o inversión en renta corta por su ubicación en el polígono central.', array['Piscina', 'Gimnasio', 'Planta full', 'Seguridad 24/7', 'Ascensor', 'Lobby']::text[], array['Ágora Mall', 'Blue Mall', 'Av. Winston Churchill']::text[], 2021, 220, false, false, null, 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=1000&q=70', false),
  ('naco-familiar', '00000000-0000-4000-8000-000000000001'::uuid, 'Apartamento familiar en Naco', 'Apartamento', 'Venta', 198000, 'Santo Domingo', 'Naco', 'Distrito Nacional', 18.477, -69.93, 3, 2, 2, 160, '3 habitaciones, calle tranquila y cerca de colegios.', 'Amplio apartamento en segundo nivel, con estudio, balcón y cuarto de servicio. Sector residencial consolidado con colegios, supermercados y farmacias a poca distancia. Edificio de 4 niveles con pocas unidades.', array['Planta full', 'Cisterna', 'Área de servicio', 'Balcón']::text[], array['Supermercado', 'Colegios', 'Av. Tiradentes']::text[], 2012, 120, false, false, null, 'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=1000&q=70', false),
  ('bella-vista-penthouse', '00000000-0000-4000-8000-000000000001'::uuid, 'Penthouse con terraza en Bella Vista', 'Penthouse', 'Venta', 520000, 'Santo Domingo', 'Bella Vista', 'Distrito Nacional', 18.456, -69.944, 3, 3.5, 3, 310, 'Dos niveles, terraza privada con jacuzzi y vista al Mirador Sur.', 'Penthouse de dos niveles con terraza techada, BBQ y jacuzzi. Habitación principal con walk-in closet y baño tipo spa. Vista despejada hacia el Mirador Sur y el mar Caribe.', array['Terraza privada', 'Jacuzzi', 'Piscina', 'Gimnasio', 'Planta full', 'Seguridad 24/7']::text[], array['Parque Mirador Sur', 'Av. Anacaona', 'Universidades']::text[], 2019, 380, false, false, null, 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1000&q=70', false),
  ('evaristo-morales-plano', '00000000-0000-4000-8000-000000000001'::uuid, 'Proyecto en plano en Evaristo Morales', 'Apartamento', 'Venta', 165000, 'Santo Domingo', 'Evaristo Morales', 'Distrito Nacional', 18.474, -69.944, 1, 1.5, 1, 82, 'Entrega en 2028, plan de pagos durante la construcción.', 'Unidades de 1 y 2 habitaciones con rooftop social, coworking y piscina. Separas con un monto inicial, pagas un porcentaje durante la construcción y el resto contra entrega, normalmente con financiamiento bancario.', array['Rooftop', 'Coworking', 'Piscina', 'Gimnasio', 'Lobby']::text[], array['Av. Abraham Lincoln', 'Plazas comerciales']::text[], null, 110, false, true, 'Diciembre 2028', 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&w=1000&q=70', false),
  ('cacicazgos-casa', '00000000-0000-4000-8000-000000000001'::uuid, 'Casa con jardín en Los Cacicazgos', 'Casa', 'Venta', 890000, 'Santo Domingo', 'Los Cacicazgos', 'Distrito Nacional', 18.451, -69.958, 4, 4.5, 4, 520, 'Casa de un nivel con piscina y amplio jardín, calle cerrada.', 'Residencia en solar de 900 m², con sala y comedor de doble altura, family room, estudio, piscina y gazebo. Calle cerrada con seguridad privada. Cerca del Mirador Sur y colegios de la zona.', array['Piscina', 'Jardín', 'Gazebo', 'Seguridad privada', 'Planta full']::text[], array['Mirador Sur', 'Colegios', 'Av. Anacaona']::text[], 2008, null, false, false, null, 'https://images.unsplash.com/photo-1564013799919-ab600027ffc6?auto=format&fit=crop&w=1000&q=70', false),
  ('arroyo-hondo-casa', '00000000-0000-4000-8000-000000000001'::uuid, 'Casa de dos niveles en Arroyo Hondo', 'Casa', 'Venta', 410000, 'Santo Domingo', 'Arroyo Hondo', 'Distrito Nacional', 18.495, -69.958, 4, 3.5, 3, 340, 'Residencial cerrado, ideal para familia grande.', 'Casa en residencial con garita, terraza trasera, cuarto de servicio con baño y cocina remodelada. Acceso rápido a la Av. Jacobo Majluta y a la Av. Kennedy.', array['Residencial cerrado', 'Terraza', 'Cuarto de servicio', 'Cisterna']::text[], array['Jardín Botánico', 'Av. Jacobo Majluta']::text[], 2014, null, false, false, null, 'https://images.unsplash.com/photo-1568605114967-8130f3a36994?auto=format&fit=crop&w=1000&q=70', false),
  ('gazcue-alquiler', '00000000-0000-4000-8000-000000000001'::uuid, 'Apartamento amueblado en Gazcue', 'Apartamento', 'Alquiler', 950, 'Santo Domingo', 'Gazcue', 'Distrito Nacional', 18.467, -69.902, 2, 1, 1, 95, 'Amueblado, cerca del Malecón y la Zona Colonial.', 'Apartamento en edificio de estilo clásico, techos altos y mucha ventilación. Incluye muebles, línea blanca y aire acondicionado en habitaciones. Contrato mínimo de un año.', array['Amueblado', 'Aire acondicionado', 'Inversor']::text[], array['Malecón', 'Zona Colonial', 'Palacio de Bellas Artes']::text[], 1995, null, false, false, null, 'https://images.unsplash.com/photo-1493809842364-78817add7ffb?auto=format&fit=crop&w=1000&q=70', false),
  ('ozama-sde', '00000000-0000-4000-8000-000000000001'::uuid, 'Apartamento económico en Ensanche Ozama', 'Apartamento', 'Venta', 89000, 'Santo Domingo Este', 'Ensanche Ozama', 'Santo Domingo', 18.488, -69.87, 3, 2, 1, 105, 'Primera vivienda, cerca del Metro y la Av. Sabana Larga.', 'Buena opción para primera vivienda. Edificio con área de juegos y cisterna. Fácil acceso al Metro de Santo Domingo y a la Av. España.', array['Área de juegos', 'Cisterna', 'Parqueo techado']::text[], array['Metro', 'Megacentro', 'Av. Sabana Larga']::text[], 2018, 45, false, false, null, 'https://images.unsplash.com/photo-1460317442991-0ec209397118?auto=format&fit=crop&w=1000&q=70', false),
  ('villa-mella-sdn', '00000000-0000-4000-8000-000000000001'::uuid, 'Casa en Villa Mella con patio', 'Casa', 'Venta', 72000, 'Santo Domingo Norte', 'Villa Mella', 'Santo Domingo', 18.565, -69.92, 3, 2, 2, 140, 'Casa de un nivel con patio y marquesina para dos vehículos.', 'Casa en proyecto cerrado, con patio trasero y espacio para ampliar en segundo nivel. Cerca de la estación del Metro Mamá Tingó y de la Autopista Duarte por la Circunvalación.', array['Patio', 'Marquesina', 'Proyecto cerrado', 'Cisterna']::text[], array['Metro Mamá Tingó', 'Av. Hermanas Mirabal']::text[], 2020, null, false, false, null, 'https://images.unsplash.com/photo-1570129477492-45c003edd2be?auto=format&fit=crop&w=1000&q=70', false),
  ('bavaro-playa', '00000000-0000-4000-8000-000000000001'::uuid, 'Apartamento cerca de la playa en Bávaro', 'Apartamento', 'Venta', 175000, 'Punta Cana', 'Bávaro', 'La Altagracia', 18.687, -68.45, 2, 2, 1, 98, 'A 5 minutos de playa Los Corales, con Confotur.', 'Residencial turístico con piscina tipo laguna y seguridad. Muy demandado para renta vacacional. El proyecto cuenta con clasificación Confotur, lo que puede reducir impuestos de transferencia y de propiedad por varios años (confirmar con abogado).', array['Piscina', 'Seguridad 24/7', 'Club house', 'Amueblado opcional']::text[], array['Playa Los Corales', 'Downtown Punta Cana', 'Aeropuerto PUJ']::text[], 2023, 150, true, false, null, 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&w=1000&q=70', true),
  ('cap-cana-villa', '00000000-0000-4000-8000-000000000001'::uuid, 'Villa frente al campo de golf en Cap Cana', 'Villa', 'Venta', 1450000, 'Punta Cana', 'Cap Cana', 'La Altagracia', 18.495, -68.38, 5, 5.5, 4, 680, 'Villa de lujo con piscina infinita y vista al golf.', 'Villa contemporánea con piscina infinita, cocina de chef, casa de huéspedes y acceso a la marina y playa privada de la comunidad. Excelente para residencia vacacional o alquiler de lujo.', array['Piscina infinita', 'Casa de huéspedes', 'Playa privada', 'Marina', 'Golf']::text[], array['Playa Juanillo', 'Marina Cap Cana', 'Aeropuerto PUJ']::text[], 2022, null, true, false, null, 'https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=1000&q=70', true),
  ('santiago-cerros', '00000000-0000-4000-8000-000000000001'::uuid, 'Casa en Los Cerros de Gurabo', 'Casa', 'Venta', 365000, 'Santiago', 'Los Cerros de Gurabo', 'Santiago', 19.47, -70.67, 4, 3.5, 3, 360, 'Vista a la ciudad y clima fresco, residencial privado.', 'Casa en zona alta de Santiago con vista panorámica, terraza y piscina. Residencial con control de acceso. Cerca de colegios y de la Av. 27 de Febrero.', array['Piscina', 'Terraza', 'Residencial privado', 'Planta full']::text[], array['Monumento', 'Av. 27 de Febrero', 'PUCMM']::text[], 2016, null, false, false, null, 'https://images.unsplash.com/photo-1580587771525-78b9dba3b914?auto=format&fit=crop&w=1000&q=70', false),
  ('santiago-villa-olga', '00000000-0000-4000-8000-000000000001'::uuid, 'Apartamento en Villa Olga', 'Apartamento', 'Venta', 138000, 'Santiago', 'Villa Olga', 'Santiago', 19.46, -70.695, 3, 2, 2, 130, 'Sector céntrico, cerca de universidades y plazas.', 'Apartamento en tercer nivel con balcón, cocina modular y área de lavado. Edificio con ascensor y planta para áreas comunes.', array['Ascensor', 'Planta áreas comunes', 'Balcón']::text[], array['PUCMM', 'Plazas comerciales', 'Av. Juan Pablo Duarte']::text[], 2017, 70, false, false, null, 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1000&q=70', false),
  ('las-terrenas', '00000000-0000-4000-8000-000000000001'::uuid, 'Villa tropical en Las Terrenas', 'Villa', 'Venta', 340000, 'Las Terrenas', 'Playa Bonita', 'Samaná', 19.32, -69.542, 3, 3, 2, 210, 'A 200 metros de Playa Bonita, rodeada de cocoteros.', 'Villa de estilo caribeño con techos de madera, piscina y jardín tropical. Zona con gran demanda de turismo europeo para renta vacacional.', array['Piscina', 'Jardín tropical', 'Amueblada', 'Seguridad']::text[], array['Playa Bonita', 'Pueblo de Las Terrenas']::text[], 2015, null, false, false, null, 'https://images.unsplash.com/photo-1499793983690-e29da59ef1c2?auto=format&fit=crop&w=1000&q=70', true),
  ('sosua-condo', '00000000-0000-4000-8000-000000000001'::uuid, 'Condominio con vista al mar en Sosúa', 'Apartamento', 'Venta', 149000, 'Sosúa', 'Sosúa', 'Puerto Plata', 19.755, -70.52, 2, 2, 1, 110, 'Vista al mar y caminable a la playa de Sosúa.', 'Condominio con piscina y terraza en cada unidad. Cerca del aeropuerto de Puerto Plata. Atractivo para retirados y renta vacacional.', array['Piscina', 'Vista al mar', 'Terraza', 'Seguridad']::text[], array['Playa de Sosúa', 'Aeropuerto POP']::text[], 2010, 130, false, false, null, 'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=1000&q=70', true),
  ('juan-dolio', '00000000-0000-4000-8000-000000000001'::uuid, 'Apartamento frente al mar en Juan Dolio', 'Apartamento', 'Venta', 210000, 'Juan Dolio', 'Juan Dolio', 'San Pedro de Macorís', 18.427, -69.43, 2, 2, 1, 120, 'Primera línea de playa, a una hora de Santo Domingo.', 'Torre frente al mar con piscina, gimnasio y acceso directo a la playa. Buena opción de segunda vivienda para familias de la capital.', array['Frente al mar', 'Piscina', 'Gimnasio', 'Planta full']::text[], array['Playa Juan Dolio', 'Autovía del Este']::text[], 2018, 190, true, false, null, 'https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1000&q=70', true),
  ('jarabacoa-cabana', '00000000-0000-4000-8000-000000000001'::uuid, 'Cabaña de montaña en Jarabacoa', 'Casa', 'Venta', 230000, 'Jarabacoa', 'Jarabacoa', 'La Vega', 19.118, -70.638, 3, 2, 2, 180, 'Clima de montaña, chimenea y vista al valle.', 'Cabaña en madera y piedra dentro de un proyecto de montaña, con chimenea, terraza y senderos. Ideal como casa de descanso o alquiler de fin de semana.', array['Chimenea', 'Terraza', 'Senderos', 'Proyecto cerrado']::text[], array['Río Yaque del Norte', 'Centro de Jarabacoa']::text[], 2019, null, false, false, null, 'https://images.unsplash.com/photo-1449158743715-0a90ebb6d2d8?auto=format&fit=crop&w=1000&q=70', false),
  ('piantini-local', '00000000-0000-4000-8000-000000000001'::uuid, 'Local comercial en Piantini', 'Local', 'Alquiler', 2800, 'Santo Domingo', 'Piantini', 'Distrito Nacional', 18.469, -69.936, 0, 1, 4, 120, 'Local a nivel de calle, alto tránsito peatonal.', 'Local en plaza comercial con vitrina a la calle, baño y parqueos para clientes. Ideal para oficina, clínica o tienda.', array['Vitrina', 'Parqueo clientes', 'Planta full']::text[], array['Av. Gustavo Mejía Ricart', 'Blue Mall']::text[], 2015, null, false, false, null, 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1000&q=70', false),
  ('la-romana-solar', '00000000-0000-4000-8000-000000000001'::uuid, 'Solar residencial cerca de Casa de Campo', 'Solar', 'Venta', 95000, 'La Romana', 'Casa de Campo', 'La Romana', 18.41, -68.91, 0, 0, 0, 800, 'Solar de 800 m² en proyecto con servicios listos.', 'Solar con título, en proyecto con calles asfaltadas, electricidad soterrada y agua. Para construir casa de descanso o villa para renta.', array['Título', 'Calles asfaltadas', 'Electricidad soterrada']::text[], array['Casa de Campo', 'Altos de Chavón']::text[], null, null, false, false, null, 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=1000&q=70', true)
